program_text='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    r, c = next((r, c) for r in range(h) for c in range(w) if grid[r][c] == 2)
    if r == 0:
        dr, dc = 1, 0
    elif r == h - 1:
        dr, dc = -1, 0
    elif c == 0:
        dr, dc = 0, 1
    elif c == w - 1:
        dr, dc = 0, -1
    else:
        raise ValueError("source not on boundary")

    queue = [(r, c, dr, dc)]
    seen = set()
    while queue:
        r, c, dr, dc = queue.pop()
        state = (r, c, dr, dc)
        if state in seen:
            continue
        seen.add(state)
        rr, cc = r, c
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] == 8:
                if dr == 0:
                    lo = hi = rr
                    while lo > 0 and grid[lo - 1][cc] == 8:
                        lo -= 1
                    while hi + 1 < h and grid[hi + 1][cc] == 8:
                        hi += 1
                    near = cc - dc
                    if 0 <= near < w:
                        for y in range(lo - 1, hi + 2):
                            if 0 <= y < h and grid[y][near] == 0:
                                out[y][near] = 2
                    for y in (lo - 1, hi + 1):
                        if 0 <= y < h and grid[y][cc] == 0:
                            queue.append((y, cc, dr, dc))
                else:
                    lo = hi = cc
                    while lo > 0 and grid[rr][lo - 1] == 8:
                        lo -= 1
                    while hi + 1 < w and grid[rr][hi + 1] == 8:
                        hi += 1
                    near = rr - dr
                    if 0 <= near < h:
                        for x in range(lo - 1, hi + 2):
                            if 0 <= x < w and grid[near][x] == 0:
                                out[near][x] = 2
                    for x in (lo - 1, hi + 1):
                        if 0 <= x < w and grid[rr][x] == 0:
                            queue.append((rr, x, dr, dc))
                break
            if grid[rr][cc] == 0:
                out[rr][cc] = 2
            rr += dr
            cc += dc
    return out
'''
p.write_text(program_text)
compile(program_text,str(p),'exec')
ns={}; exec(compile(program_text,str(p),'exec'),ns)
print('saved',p,'bytes',p.stat().st_size)
